import { IS_NON_DIMENSIONAL } from '../constants';

/**
 * Names and patterns used when mapping VNode props onto a DOM node.
 */
export function PropBinder() {
	this.styleName = 'style';
	this.innerHTMLName = 'dangerouslySetInnerHTML';
	this.capturePattern = /Capture$/;
	this.svgHrefPattern = /xlink[H:h]/;
	this.svgClassPattern = /sName$/;
}

PropBinder.prototype.setStyle = function(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
};

export const propBinder = new PropBinder();

